'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Complex128Array = require( '@stdlib/array/complex128' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var zlastIndexOfFalsy = tryRequire( resolve( __dirname, './../lib/ndarray.native.js' ) );
var opts = {
	'skip': ( zlastIndexOfFalsy instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof zlastIndexOfFalsy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 4', opts, function test( t ) {
	t.strictEqual( zlastIndexOfFalsy.length, 4, 'has expected arity' );
	t.end();
});

tape( 'the function returns the index of the last falsy element', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex128Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 0.0, 0.0, 0.0, 0.0, 4.0, 5.0 ] );

	actual = zlastIndexOfFalsy( 6, x, 1, 0 );
	t.strictEqual( actual, 4, 'returns expected value' );

	actual = zlastIndexOfFalsy( x.length-1, x, 1, 1 );
	t.strictEqual( actual, 4, 'returns expected value' );

	actual = zlastIndexOfFalsy( 3, x, -2, x.length-1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'if provided an N parameter less than or equal to 0, the function returns -1', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex128Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0 ] );

	actual = zlastIndexOfFalsy( 0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = zlastIndexOfFalsy( -1, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an x stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex128Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 3.0, 4.0, 0.0, 0.0, 5.0, 6.0 ] );

	actual = zlastIndexOfFalsy( 3, x, 2, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports negative strides', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex128Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 3.0, 4.0, 0.0, 0.0 ] );

	actual = zlastIndexOfFalsy( 3, x, -2, x.length-1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an offset parameter', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex128Array( [ 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 0.0, 0.0 ] );

	actual = zlastIndexOfFalsy( 2, x, 1, 3 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', opts, function test( t ) {
	var actual;
	var x;

	x = new Complex128Array( [ 0.0, 0.0, 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 0.0, 0.0 ] );

	actual = zlastIndexOfFalsy( 3, x, 2, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports view offsets', opts, function test( t ) {
	var actual;
	var x0;
	var x1;

	x0 = new Complex128Array( [ 1.0, 2.0, 0.0, 0.0, 2.0, 3.0, 3.0, 4.0, 0.0, 0.0 ] );

	x1 = new Complex128Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	actual = zlastIndexOfFalsy( 3, x1, 2, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});
